// ===== 설정 (여기만 수정하세요) =====
const API_KEY = 'AIzaSyDI0pjUJBjW2zorcIDkL7G1LCsd21gNmNQ';
const MAX_VIDEOS_PER_QUERY = 10;               // 검색어당 영상 수 (최대 50)
const PUBLISHED_AFTER = '2021-01-01T00:00:00Z';
const SKIP_PREVIOUS_VIDEOS = true;             // 1차 수집 때 가져온 영상 73개는 건너뜀 (중복 방지)

// 가설별 검색어. 유튜브 검색 1회 = 할당량 100 (하루 기본 10,000)
const QUERIES = {
  'H3 스마트진단':      ['LG 에어컨 스마트진단', 'LG 스마트진단 하는 법', '씽큐 스마트진단 에어컨', 'LG ThinQ 진단 기능', '휘센 자가진단'],
  'H3 ThinQ 진입':      ['LG 씽큐 에어컨 등록', 'LG 씽큐 연결 안됨', 'LG ThinQ 앱 사용법 에어컨'],
  'H3 상담·AS 전환':    ['LG전자 서비스 접수 후기', 'LG전자 고객센터 상담 후기', 'LG 에어컨 AS 후기', 'LG 에어컨 출장비'],
  'H2 자가 해결':       ['에어컨 기사 부르기 전 확인', 'LG 에어컨 고장 아닌 경우', 'LG 에어컨 자가점검', 'LG 에어컨 안 켜질 때', 'LG 에어컨 리모컨 실내기 선택', '에어컨 차단기 리셋 LG'],
};
const PREVIOUS_VIDEO_IDS = ['-gH70sNfs8o','-ld9eQIVKjQ','0IWINQerug4','17NZomj0mag','2Zhuww701m8','3AifL_NuRik','3zlMDgYan7g','4TkM0MqHlEc','6biC9Rt0U7A','75rJfkp3Jjs','8ULmmsxzk8U','AZpkg3p3Rzs','A_gPWELqQ9k','Aq4HLnR9DaI','BMV-g4mUiwI','BNQLhVyd8mo','Bt3IGZsJDMY','FhKgiZUoK10','Gv-pmw4PMeU','HM8EoX6gPn8','HPcPl9daUJQ','IlVXsn3CXzE','JEpnXXpeswM','KPpibLd0x4w','LCJyOHdyaZg','LWLeN7UFy_Y','POvkU44GrPA','QcmXeeTDb9Q','R3Xa4n1LnIs','Sor1aV_OBbA','T0scB2fskso','T1d5JQDnZQc','T2-iYxv1SqM','TEOXLKoUhuA','Tw1gHik7oug','U886aFB_npk','WntP9-7KyKY','XEyzYBnR2Fw','XOS2dQJcoCw','Z3aodyLhzuA','ZT1HucsTyeQ','_3eE-U7ehpE','_DUSoyR9kts','_yYHWQQ8rrc','aOLnN9lmdW4','aVQ9RuzBxf8','bdVtXDquLvo','cuXCjWqcYPs','ddnjApZk8S8','dg_KxBX0BlM','e1LuoWehoLk','eeUaP29xoqw','faMIUrTos7w','fbiZ42pIYBA','gTpSuBVYHCQ','gnTpjuy349U','lFEn4n21prw','nzOUHbQ6Vlk','oSwCrWQ9Gwo','odIfX9gT9n8','pH3D6-DEaaA','rbEv2YnvsPA','rmVUUqDvbmc','s9ohfBKnF8I','t0fvQyEab_I','tV90Te6Oo1U','upo0-x0nG-Y','vM6FNmtKnJQ','vdrKpDyusMY','wUWv0xFiDrA','yP-2PfaLXd4','yVjT3w6TmoM','zdJ3fD6yRuk'];

const out = [];
for (const [group, list] of Object.entries(QUERIES)) {
  for (const q of list) out.push({ json: { query: q, group, apiKey: API_KEY, maxResults: MAX_VIDEOS_PER_QUERY, publishedAfter: PUBLISHED_AFTER,
    skipIds: SKIP_PREVIOUS_VIDEOS ? PREVIOUS_VIDEO_IDS : [] } });
}
return out;

// 검색 결과 → 영상 목록 (중복·이전 수집 영상 제거, LG/스마트진단 관련 영상만)
const ONLY_RELATED_VIDEOS = true;
const RELATED_RE = /LG|엘지|휘센|whisen|오브제|씽큐|thinq|스마트\s*진단|자가\s*진단|자가\s*점검/i;

const queries = $('검색어 생성').all();
const apiKey = queries[0].json.apiKey;
const skip = new Set(queries[0].json.skipIds || []);
const decode = s => String(s || '').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>');

const map = new Map();
$input.all().forEach((item, i) => {
  const idx = (item.pairedItem && item.pairedItem.item !== undefined) ? item.pairedItem.item : i;
  const q = (queries[idx] || {}).json || {};
  for (const v of (item.json.items || [])) {
    const id = v.id && v.id.videoId;
    if (!id || skip.has(id)) continue;
    const sn = v.snippet || {};
    const title = decode(sn.title);
    if (ONLY_RELATED_VIDEOS && !RELATED_RE.test(title + ' ' + decode(sn.description) + ' ' + decode(sn.channelTitle))) continue;
    if (map.has(id)) { map.get(id).queries.add(q.query); map.get(id).groups.add(q.group); continue; }
    map.set(id, { videoId: id, videoTitle: title, channel: decode(sn.channelTitle), queries: new Set([q.query]), groups: new Set([q.group]) });
  }
});
return [...map.values()].map(v => ({ json: { ...v, queries: [...v.queries].join(' | '), groups: [...v.groups].join(' | '), apiKey } }));

// 댓글·답글 펼치기 → 가설 1·2·3 신호 태깅
const MIN_LEN = 8;
const KEEP_ONLY_RELEVANT = true; // 아래 신호가 하나라도 있는 댓글만 남김

const SYMPTOMS = {
  '냉방불량': /찬\s*바람이?\s*안|안\s*시원|시원하지\s*않|냉방이?\s*(약|안)|미지근|온도가?\s*안\s*(내려|떨어)/,
  '냄새': /냄새|쉰내|악취|곰팡/,
  '물샘': /물이?\s*(새|샘|떨어|뚝뚝|흘러|넘)|누수|물샘|배수/,
  '소음': /소음|시끄|소리가|소리\s*(나|남)|덜덜|웅웅|윙윙|딸깍|진동/,
  '에러코드': /CH\s?-?\d{1,3}|에러\s*코드|오류\s*코드|에러\s*뜨|에러가/i,
  '작동이상': /꺼져|꺼짐|꺼지|안\s*켜|안\s*돌|작동\s*(이\s*)?안|멈춰|멈춤|실외기가?\s*안|깜빡/,
  '결빙·냉매': /성에|얼음|결빙|냉매|가스\s*(충전|보충|부족)/,
  '리모컨·설정': /리모컨|리모콘|실내기\s*선택|예약|설정/,
};
// 가설 1: 원인·다음 행동 판단 어려움
const CAUSE_UNSURE = /왜\s*(그런|이러|이렇|그럴|안|자꾸|계속)|원인이|원인을|원인\s*(이\s*)?뭘|뭐가\s*문제|무슨\s*문제|이유가|고장\s*인가|고장인지|정상\s*인가|정상인지|이게\s*맞나|모르겠/;
const ACTION_UNSURE = /어떻게\s*(해야|하면|하나요|하죠)|어떡하|어쩌죠|해야\s*(하나요|할까|되나|돼요|되나요)|불러야|(a\s*\/?\s*s|수리)\s*(를\s*)?(받아야|불러야|신청해야)|방법\s*(이|좀)?\s*(있|알려|없)|해결\s*(방법|이\s*안|못)|알려\s*주세요|도와\s*주세요/i;
// 가설 2: 상담·AS 전에 자가 해결 가능했던 상황
const SELF_FIXED = /해결\s*(했|됐|되었)|됐어요|되네요|되더라|작동\s*(하네|되네|됐)|살았|고쳤|덕분에\s*(해결|고쳐)/;
const NEAR_AS = /(기사|as|a\/s|서비스)\s*(를\s*)?(부르|부를|부르려|신청|접수)[^.?!]{0,15}(뻔|전에|했는데|하려다|했다가)|부를\s*뻔|부르려다|신청\s*(했는데|하고)/i;
const USER_SIDE = /리모컨\s*(설정|건전지|배터리)|실내기\s*선택|차단기|루버|필터\s*(청소|막)|전원\s*(코드|플러그)|리셋|껐다\s*켜|콘센트|모드\s*(가|를)?\s*(잘못|바뀌)/;
// 가설 3: 스마트진단·ThinQ·상담 진입/전환
const DIAG = /스마트\s*진단|자가\s*진단|씽큐\s*진단|thinq\s*진단|진단\s*(결과|했|해\s*보|돌려|기능|모드)/i;
const DIAG_MISMATCH = /진단[^.?!]{0,30}(정상|이상\s*없|문제\s*없)/;
const THINQ = /씽큐|thinq|띵큐|앱으로|어플/i;
const CS = /고객\s*센터|상담|1544|챗봇|1:1|콜센터|전화|접수|센터에/;
const AS_VISIT = /기사|a\s*\/?\s*s|출장|수리|방문/i;
const FRICTION = /연결\s*(이\s*)?안|등록\s*(이\s*)?안|인식\s*(이\s*)?안|못\s*찾|어디(서|에|있)|찾을\s*수\s*없|메뉴|소리.{0,10}(안\s*들|인식)|대기\s*(가|시간)|전화\s*(가\s*)?안|연결\s*(이\s*)?어려|답변\s*(이\s*)?(없|안)|기다리|일주일|한\s*달|순서|복잡|어렵/;
const TRIED = /해\s*봤|해봤|했는데|했는데도|했지만|그래도|여전히|그대로/;
const NEGATIVE = /짜증|화나|열받|최악|다시는|후회|환불|스트레스|답답|황당|어이없|실망/;

const videos = new Map($('영상 목록 정리').all().map(i => [i.json.videoId, i.json]));
const today = new Date().toISOString().slice(0, 10);
const seen = new Set();
const rows = [];
const Y = b => b ? 'Y' : '';

function add(sn, commentId, isReply, parentText, replyCount, videoId) {
  if (!sn || seen.has(commentId)) return;
  seen.add(commentId);
  const text = String(sn.textOriginal || sn.textDisplay || '').replace(/\s+/g, ' ').trim();
  if (text.length < MIN_LEN) return;
  if (/https?:\/\//.test(text) && /구매|할인|쿠팡|링크|교육/.test(text)) return;

  const symptoms = Object.entries(SYMPTOMS).filter(([, re]) => re.test(text)).map(([k]) => k);
  const cause = CAUSE_UNSURE.test(text), action = ACTION_UNSURE.test(text);
  const selfFixed = SELF_FIXED.test(text), nearAs = NEAR_AS.test(text), userSide = USER_SIDE.test(text);
  const diag = DIAG.test(text), thinq = THINQ.test(text), cs = CS.test(text), as = AS_VISIT.test(text);
  const friction = FRICTION.test(text) && (diag || thinq || cs || as);

  const h1 = (cause || action) && (symptoms.length > 0 || /\?/.test(text));
  const h2 = nearAs || (selfFixed && (userSide || symptoms.length > 0));
  const h3 = diag || friction;
  if (KEEP_ONLY_RELEVANT && !h1 && !h2 && !h3 && symptoms.length === 0 && !cs && !thinq) return;

  const v = videos.get(videoId) || {};
  rows.push({ json: {
    '수집일': today,
    '가설그룹': v.groups || '',
    '검색어': v.queries || '',
    '영상제목': v.videoTitle || '',
    '채널': v.channel || '',
    '영상URL': `https://www.youtube.com/watch?v=${videoId}`,
    '댓글URL': `https://www.youtube.com/watch?v=${videoId}&lc=${commentId}`,
    '구분': isReply ? '답글' : '댓글',
    '원댓글': isReply ? parentText : '',
    '댓글내용': text,
    '좋아요': sn.likeCount || 0,
    '답글수': isReply ? '' : (replyCount || 0),
    '작성일': String(sn.publishedAt || '').slice(0, 10),
    '증상분류': symptoms.join(', '),
    'H1_원인모름': Y(cause),
    'H1_다음행동모름': Y(action),
    'H2_자가해결': Y(selfFixed),
    'H2_AS부르기직전': Y(nearAs),
    'H2_사용자쪽원인언급': Y(userSide),
    'H3_스마트진단언급': Y(diag),
    'H3_진단은정상인데문제': Y(diag && DIAG_MISMATCH.test(text)),
    'H3_ThinQ앱언급': Y(thinq),
    'H3_상담·고객센터언급': Y(cs),
    'H3_AS·기사언급': Y(as),
    'H3_진입·전환불편': Y(friction),
    '이미시도한조치': Y(TRIED.test(text)),
    '부정감정': Y(NEGATIVE.test(text)),
    '가설1후보': Y(h1), '가설2후보': Y(h2), '가설3후보': Y(h3),
    '댓글ID': commentId,
  }});
}

for (const item of $input.all()) {
  for (const t of (item.json.items || [])) {
    const s = t.snippet || {};
    const top = s.topLevelComment || {};
    const topText = String((top.snippet || {}).textOriginal || '').replace(/\s+/g, ' ').trim();
    add(top.snippet, top.id, false, '', s.totalReplyCount, s.videoId);
    for (const r of ((t.replies || {}).comments || [])) add(r.snippet, r.id, true, topText.slice(0, 300), 0, s.videoId);
  }
}
const score = j => (j['가설3후보'] ? 4 : 0) + (j['가설2후보'] ? 2 : 0) + (j['가설1후보'] ? 1 : 0);
rows.sort((a, b) => score(b.json) - score(a.json) || b.json['좋아요'] - a.json['좋아요']);
return rows;
